#include "const.h"
#include "src/WLEDpixelBus/WLEDpixelBus.h" // MAX_CUSTOM_CHANNELS, LedTiming

enum LedTypeFlags : uint8_t {
  LT_W       = 0x01, // has a white channel (WW on CCT types)
  LT_CCT     = 0x02, // warm and cool white
  LT_16BIT   = 0x04, // 16 bits per channel
  LT_REFRESH = 0x08, // needs data while off
  LT_NORGB   = 0x10, // no RGB channels (white-only types)
};

struct LedTypeDef {
  uint8_t  id;
  const char* name;  // shown in the LED settings type list
  uint8_t  flags;     // LedTypeFlags
  char     layout[7]; // wire channels at color order 0 ("GRB"): R, G, B, W (WW on CCT types), C (CW), '-' = unused byte
  uint16_t t0h, t0l, t1h, t1l; // bit timing, ns
  uint16_t trst;               // reset/latch gap, us
  uint8_t  gaps[WLEDpixelBus::MAX_CUSTOM_CHANNELS]; // zero bits before each wire channel (bit-packed types)
};

